(()=>{
 'use strict';
 const records=window.portfolioCollection,stage=document.querySelector('#story-stage');
 const record=id=>records.find(r=>r.id===id);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const photo=(id,n=0)=>record(id)?.images?.[n]?.src;
 const image=(src,alt,cls='')=>`<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
 const detail=(id,label='Inside the project')=>`<button class="story-link" type="button" data-project="${id}">${label} <span aria-hidden="true">↗</span></button>`;
 const film=(id,label)=>`<button class="film-window layer" data-direction="right" data-project="${id}" type="button" aria-label="Watch ${esc(label)}">${image(photo(id),label)}<span class="film-play"><span aria-hidden="true">▶</span> Watch ${label}</span></button>`;
 const copy=(label,title,body,links='')=>`<div class="chapter-copy layer" data-direction="left"><p class="eyebrow">${label}</p><h2>${title}</h2><p class="chapter-description">${body}</p><div class="chapter-links">${links}</div></div>`;
 const chapters=[
 {id:'work',name:'What comes next?',theme:'light',kind:'invitation',html:`<div class="invitation-copy layer" data-direction="bottom"><p class="eyebrow">Pioneering new ways to learn, connect and create</p><h2>What could we<br><em>build together?</em></h2><p>A new product. A live experience. A team ready to do something it hasn’t done before.</p><div class="invitation-actions"><a class="primary-action" href="mailto:aaronjonesvideo@gmail.com?subject=Let%E2%80%99s%20arrange%20a%20call">Let’s arrange a call</a><a class="story-link" href="#origins">Follow the story ↓</a><button class="story-link" data-library>Explore all the work</button></div></div><div class="invitation-reel layer" data-direction="right">${['good-omen','rory','creative-community'].map(id=>`<button data-project="${id}" aria-label="Explore ${esc(record(id).title)}">${image(photo(id),record(id).title)}</button>`).join('')}</div><p class="chapter-tail">Scroll to see how one breakthrough leads to the next.</p>`},
 {id:'origins',name:'A different kind of business',theme:'light',html:copy('The beginning / Fikay','It started with<br>a different way<br>to do business.','At nineteen, I wanted to build a business that created opportunity. Fikay connected ethical fashion, livelihoods and education. It taught me that a new idea matters when you bring people into it.',detail('fikay','The Fikay story'))+`<div class="evidence-composition layer" data-direction="right">${image('assets/aaron-fikay.jpg','Aaron Jones, University of Essex profile','portrait-evidence')}<div class="recognition-card depth-layer" data-depth=".6"><span>British Empire Medal</span><strong>Services to<br>ethical fashion</strong><small>2016 · Alumnus of the Year, Essex · 2018</small></div></div>`},
 {id:'discovery',name:'A new way to discover',theme:'dark',html:copy('Visual search / SeeFashion','What if the image<br>was the question?','Twelve years ago, I was exploring visual search. With SeeFashion, I built around computer vision and discovery: helping people find what they meant, even when they didn’t have the words.',detail('seefashion','Visual search and discovery'))+`<div class="discovery-art layer" data-direction="top"><span class="diagram-label">The shift in interaction</span><div class="search-question"><span>Describe what you’re looking for…</span><strong>Show me.</strong></div><div class="discovery-flow"><span>Image</span><i>→</i><span>Understanding</span><i>→</i><span>Discovery</span></div><p>From searching with words<br>to searching with what we see.</p><span class="diagram-note">A concept diagram, not a product screenshot</span></div>`},
 {id:'generated-video',name:'A new way to communicate',theme:'dark',html:copy('Generative video / Yepic AI','Then an image<br>became a voice.','I started building with AI video in 2019. At Yepic, we brought researchers and engineers together to create video generation and live communication systems—years before the current wave of AI video tools.',detail('video-foundations','The early generative video work'))+`<div class="video-era layer" data-direction="right"><div class="source-to-video">${image('assets/aaron-portrait.jpg','Aaron Jones','depth-layer')}<span class="era-equation">A portrait.<br>A voice.<br>A new conversation.</span></div><div class="era-proof"><strong>1 million+</strong><span>Yepic Studio videos generated<br>Documented by OVHcloud, 2022</span></div></div>`},
 {id:'connections',name:'From video to a conversation',theme:'light',html:copy('Live AI / Conversations, not just clips','And then it<br>could answer back.','We gave people a way to talk with an AI persona: to confess a marketing sin, explore a conference or practise their first interview. My work joined the models, the interface and the live experience.',detail('rory','Rory at MADFest')+detail('live-hosts','London Tech Week')+detail('international','AI interview coach'))+`<div class="live-composition layer" data-direction="right">${film('rory','AI Rory')}<button class="supporting-frame depth-layer" data-depth=".45" data-project="live-hosts">${image(photo('live-hosts'),'London Tech Week AI hosts')}<span>London Tech Week · Live knowledge</span></button></div>`},
 {id:'cinema-breakthrough',name:'A new way to make cinema',theme:'dark',kind:'wide-film',html:`<div class="wide-film-heading layer" data-direction="top"><p class="eyebrow">Big Screen Hack / Cannes</p><h2>48 hours.<br><em>Then the big screen.</em></h2><p>I brought filmmakers and AI engineers together to make films, then share them with a cinema audience during Cannes festival week.</p></div>${film('creative-community','lilies')}<div class="film-attribution">Film: <strong>lilies</strong> · Muja Studios / Jabir Mohammed<br>My role: organising the people, partners and experience.<br><span>Independent screening at Cinéum Cannes · May 2026</span></div>`},
 {id:'together',name:'The teams that make it happen',theme:'light',html:copy('Good Omen / Two hackathon wins','The right people.<br>Something none of us<br>could build alone.','With Giovanni Funchal and Marko Stapfner, I won the AI Engine Summer Hack and Project Europe × Lovable. In Stockholm we built two products in under twenty hours. Impact Loop acquired the journalist tool.',detail('good-omen','The Stockholm win')+detail('ai-engine','The Summer Hack win'))+`<div class="winning-composition layer" data-direction="right">${image('assets/good-omen-stockholm.jpg','Good Omen celebrating with Impact Loop. Photograph: Jesper Andersson.','winning-main')}<figure class="winning-detail depth-layer" data-depth=".5">${image('assets/good-omen-summer.jpeg','Good Omen presenting at Summer Hack. Photograph: Adam Isfendiyar.')}<figcaption>Build together. Learn together.</figcaption></figure></div>`},
 {id:'frontier',name:'The next frontier',theme:'dark',html:copy('Now / World models + StoryMachine','What if the world<br>could respond<br>as you imagine it?','My work is moving from generating clips to real-time, interactive worlds. With StoryMachine, I’m bringing research, planning and creative exploration together—so a team can shape an idea while it is still taking form.',detail('world-models','World models and real-time video')+detail('storymachine','Why I’m building StoryMachine')+detail('open-source','Research and open source'))+`<div class="frontier-diagram layer" data-direction="bottom"><span class="diagram-label">The direction I’m building towards</span><ol><li><span>01</span><strong>Imagine</strong><small>A person sets the direction.</small></li><li><span>02</span><strong>Explore</strong><small>Agents help develop possibilities.</small></li><li><span>03</span><strong>Respond</strong><small>The experience changes with you.</small></li></ol><p>Real-time · Interactive · Collaborative</p><span class="diagram-note">Research direction, not a live model demo</span></div>`},
 {id:'build-with-you',name:'Your next breakthrough',theme:'light',html:copy('Strategy + engineering + delivery','The next difficult<br>problem could<br>be yours.','I work with clients from the first conversation through to the build. Sometimes that means a private AI system on local hardware. Sometimes it means helping a leadership team decide where to start—and giving their people the skills to do it.',detail('research','On-premise AI · Oracle + Abu Dhabi Aviation')+detail('oman','AI video at national scale · Oman')+detail('ai-consulting','Consulting and team training'))+`<div class="client-path layer" data-direction="right"><p>How I work with you</p><ol><li><span>Listen</span><strong>What are you trying to change?</strong></li><li><span>Find the possibility</span><strong>What can the technology do now?</strong></li><li><span>Build it together</span><strong>What will make it work in your world?</strong></li></ol><a class="primary-action" href="mailto:aaronjonesvideo@gmail.com?subject=I%20have%20a%20project">Tell me about the project</a></div>`},
 {id:'contact',name:'Let’s talk',theme:'dark',html:copy('Build with me / Bring me to your stage','Let’s make<br>something<br>happen.','A research challenge, a product, a room full of people ready to explore what comes next. Tell me what you have in mind.',`<a class="primary-action" href="mailto:aaronjonesvideo@gmail.com?subject=Let%E2%80%99s%20arrange%20a%20call">Arrange a call</a><a class="story-link" href="mailto:aaronjonesvideo@gmail.com?subject=Speaking%20enquiry">Book me to speak</a><a class="story-link" href="mailto:aaronjonesvideo@gmail.com?subject=Role%20opportunity">Talk about a role</a>`)+`<figure class="closing-portrait layer" data-direction="right">${image('assets/saudi-speaking.jpeg','Aaron Jones speaking at DeepFest and LEAP in Saudi Arabia')}<figcaption>Builder first. On stage, too.</figcaption></figure>`}
 ];
 for(const c of chapters){const section=document.createElement('section');section.id=c.id;section.className='film-scene '+(c.kind||'');section.dataset.title=c.name;section.dataset.theme=c.theme;section.setAttribute('aria-label',c.name);section.innerHTML=c.html.replaceAll('<br>','<br> ');stage.append(section)}
 window.PortfolioNarrative={chapters,record,esc};
})();
